"""ExecutionAgent: generated by G2C for E2A v1.2; completed by hand.

The only material step. It runs after an approved proposal (the approval stage pauses the
workflow here until a second person decides; resume() continues). _prepare re-reads the
settlement: it must still be COMPLETED. _act posts the adjustment through io_modify with the
workflow's idempotency key, so a retried or replayed approval never posts twice; the tool reads
the ledger back. The receipt (outcome, adjustment id, read-back) is kept in the run's state."""
import logging

from e2a import BaseAgent, PhysicalOutcome


class ExecutionAgent(BaseAgent):
    agent_name = 'ExecutionAgent'

    def _prepare(self, state, ctx, io_read):
        """Read the facts this agent needs (replay-safe reads; no side effects)."""
        proposal = state['proposal']
        current = io_read.call('get_settlement', {'settlement_id': proposal['settlement_id']})
        state['settlement_now'] = (current.get('body') or {}) if current.get('physical_success') else None

    def _build_messages(self, state, ctx):
        return None                      # deterministic: no model step

    def _act(self, state, ctx, io_modify):
        """Material effects, only after the approval: the call carries the idempotency key and returns a
        typed outcome (COMMITTED / NOT_COMMITTED / UNKNOWN)."""
        proposal, now = state['proposal'], state.get('settlement_now')
        if not now or now.get('status') != 'COMPLETED':
            state['receipt'] = {'outcome': 'NOT_COMMITTED', 'detail': 'the settlement is no longer COMPLETED'}
            return [PhysicalOutcome.NOT_COMMITTED]
        result = io_modify.call('post_adjustment', {
            'settlement_id': proposal['settlement_id'],
            'json': {'type': proposal['action'], 'amount': proposal['amount'],
                     'reason': proposal['reason'][:500], 'reference': f'genai-{ctx.idempotency_key}'[:100]}},
            idempotency_key=ctx.idempotency_key)
        body = result.get('body') or {}
        outcome = result.get('outcome')
        state['receipt'] = {'outcome': getattr(outcome, 'value', str(outcome)), 'status': result.get('status'),
                            'adjustment_id': body.get('adjustmentId'), 'read_back': result.get('read_back'),
                            'approved_by': state.get('approved_by'), 'idempotency_key': ctx.idempotency_key,
                            'detail': body.get('error') or body.get('reason')}
        return [outcome]

    def _handle_error(self, error, state, ctx):
        logging.error(f'[ExecutionAgent] {error}')
        state.setdefault('errors', []).append(str(error))
